-- Улучшенный профессиональный HTML-шаблон письма клиенту
UPDATE site_settings
SET value = E'<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f4f4f8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif">\n<table width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f8;padding:32px 16px">\n<tr><td align="center">\n<table cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08)">\n<!-- Header -->\n<tr><td style="background:linear-gradient(135deg,#f97316 0%,#ea580c 100%);padding:32px 32px 28px;text-align:center">\n<div style="width:56px;height:56px;background:rgba(255,255,255,0.2);border-radius:14px;display:inline-block;line-height:56px;margin-bottom:12px">\n<span style="font-size:28px">✓</span>\n</div>\n<h1 style="color:#fff;margin:0;font-size:24px;font-weight:700">Заявка принята!</h1>\n<p style="color:rgba(255,255,255,0.9);margin:6px 0 0;font-size:14px">{company_name}</p>\n</td></tr>\n<!-- Body -->\n<tr><td style="padding:32px">\n<p style="margin:0 0 16px;color:#1a1a1a;font-size:16px;line-height:1.5">\nЗдравствуйте, <b>{name}</b>!\n</p>\n<p style="margin:0 0 24px;color:#4a4a4a;font-size:15px;line-height:1.6">\nВаша заявка успешно зарегистрирована в нашей системе. Менеджер свяжется с вами в течение <b style="color:#f97316">15 минут</b> по телефону {phone}.\n</p>\n<!-- Order box -->\n<table width="100%" cellpadding="0" cellspacing="0" style="background:#fff7ed;border:2px solid #fed7aa;border-radius:12px;margin-bottom:24px">\n<tr><td style="padding:20px;text-align:center">\n<div style="font-size:11px;color:#9a3412;text-transform:uppercase;letter-spacing:1.5px;font-weight:600;margin-bottom:6px">Номер вашей заявки</div>\n<div style="font-family:Menlo,Monaco,monospace;font-size:24px;color:#c2410c;font-weight:700">{order_num}</div>\n</td></tr>\n</table>\n<!-- Details -->\n<table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px">\n<tr><td style="padding:10px 0;border-bottom:1px solid #eee;font-size:14px;color:#666;width:40%">Услуга</td><td style="padding:10px 0;border-bottom:1px solid #eee;font-size:14px;color:#1a1a1a;font-weight:500">{object_type}</td></tr>\n<tr><td style="padding:10px 0;border-bottom:1px solid #eee;font-size:14px;color:#666">Город</td><td style="padding:10px 0;border-bottom:1px solid #eee;font-size:14px;color:#1a1a1a">{city}</td></tr>\n</table>\n<!-- CTA -->\n<table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:8px">\n<tr><td align="center" style="padding:16px;background:#fef3e2;border-radius:12px">\n<div style="font-size:13px;color:#666;margin-bottom:8px">Срочные вопросы?</div>\n<a href="tel:{company_phone}" style="font-size:20px;font-weight:700;color:#c2410c;text-decoration:none">📞 {company_phone}</a>\n</td></tr>\n</table>\n</td></tr>\n<!-- Footer -->\n<tr><td style="background:#fafafa;padding:20px 32px;text-align:center;border-top:1px solid #eee">\n<p style="margin:0;font-size:12px;color:#999">\nС уважением, команда <b>{company_name}</b><br>\n{company_email}\n</p>\n</td></tr>\n</table>\n</td></tr></table></body></html>'
WHERE key = 'client_email_html';